import "server-only";
import fs from "node:fs";
import path from "node:path";
import type { PracticeTest, TestIndexRow } from "./test-types";

// Practice tests (past papers), generated by `npm run tests:build` (runs automatically before dev/build).
const DIST = path.join(process.cwd(), "content", "tests", "dist");

export function getTestIndex(): TestIndexRow[] {
  return JSON.parse(fs.readFileSync(path.join(DIST, "index.json"), "utf8"));
}

export function getTest(id: string): PracticeTest | null {
  if (!/^[\w-]+$/.test(id)) return null;
  const p = path.join(DIST, `${id}.json`);
  return fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, "utf8")) : null;
}
